"""Authored synthetic phrases; test wording comes from different template families."""
from model import LABELS
PHRASES = {
'hot_water':['آب گرم ندارم','آب حمام سرده','آب مصرفی گرم نمیشه','دوش آب گرم نمیاد','آب شیر سرد مونده','آب گرم قطع شده','آب موقع استحمام گرم نیست','آب مصرفی سرد است'],
'heating':['رادیاتور سرده','شوفاژ گرم نمیشه','گرمایش خونه کار نمی کنه','همه رادیاتورها سردن','پکیج گرمایش نداره','اتاق گرم نمیشه','رادیاتور اتاق سرد مانده','خانه گرما ندارد'],
'leak':['از پکیج آب می چکه','نشتی آب داریم','زیر دستگاه خیس شده','رادیاتور آب پس میده','لوله آب نشتی داره','آب از دستگاه میریزه','کف زیر پکیج آب جمع شده','قطره های آب از رادیاتور می ریزه'],
'error_code':['پکیج ارور میده','کد خطا روی صفحه هست','نمایشگر خطا نشان میده','چراغ ارور روشنه','دستگاه کد ۴۰ میده','پکیج خطای e1 داره','صفحه نمایش دستگاه پیغام خطا دارد','روی نمایشگر کد e2 ظاهر شده'],
'noise':['پکیج صدا میده','دستگاه تق تق می کنه','صدای غیرعادی از شوفاژ میاد','رادیاتور صدا داره','پکیج سوت می کشه','صدای دستگاه زیاده','از رادیاتور صدای ضربه شنیده می شود','دستگاه صدای عجیبی تولید می کند'],
'maintenance':['سرویس دوره ای میخوام','وقت سرویس پکیج هست','برای نگهداری دستگاه کمک میخوام','سرویس سالانه انجام میدید','پکیجم نیاز به سرویس داره','درخواست سرویس رادیاتور دارم','می خواهم دستگاه را سرویس کنید','برای بازدید سالانه وقت می خواهم'],
'installation':['نصب پکیج میخوام','رادیاتور جدید نصب می کنید','میخوام دستگاه رو نصب کنم','نصاب شوفاژ لازم دارم','پکیج خریدم نصب میخوام','نصب دستگاه جدید انجام میدید','برای راه اندازی دستگاه نو نصاب می خواهم','پکیج تازه را چه کسی نصب می کند'],
'price':['قیمت پکیج چنده','هزینه خرید رادیاتور چقدره','لیست قیمت دارید','قیمت دستگاه میخوام','پکیج چند می فروشید','رادیاتور چنده','بهای خرید پکیج را می خواهم','خرید رادیاتور چقدر هزینه دارد']}
def split_data():
    # Split base phrases before augmentation, so exact families cannot leak.
    training=[]; validation=[]; challenge=[]
    for label in LABELS:
        for i,phrase in enumerate(PHRASES[label]):
            target=training if i<5 else validation if i==5 else challenge
            for prefix in (['','سلام ','لطفا کمک کنید '] if i<5 else ['']): target.append({'text':prefix+phrase,'label':label,'family':f'{label}-{i}'})
    return training,validation,challenge
